syntax:
Stack(
  children: [
    Widget, // القاعدة
    Positioned(top: 8, right: 8, child: Widget), // فوقها بموضع محدد
  ],
)

example:
Stack(
  children: [
    Image.network('https://picsum.photos/200', width: 200, height: 150),
    Positioned(
      top: 8,
      right: 8,
      child: Icon(Icons.favorite, color: Colors.red),
    ),
  ],
)

Center(
  child: Text('نص في المنتصف تمامًا'),
)

syntax:
Row(
  children: [
    Widget, // حجم ثابت
    Expanded(child: Widget), // يأخذ الباقي
  ],
)

example:
Row(
  children: [
    Icon(Icons.person),
    SizedBox(width: 8),
    Expanded(
      child: Text(
        'نص طويل جدًا قد يفيض بدون Expanded حوله بهذا المكان بالضبط',
        overflow: TextOverflow.ellipsis,
      ),
    ),
  ],
)

Row(
  children: [
    TextButton(onPressed: () {}, child: Text('إلغاء')),
    ElevatedButton(onPressed: () {}, child: Text('تأكيد')),
  ],
)

final controller = TextEditingController();

TextField(
  controller: controller,
  decoration: InputDecoration(
    labelText: 'البريد الإلكتروني',
    border: OutlineInputBorder(),
  ),
  keyboardType: TextInputType.emailAddress,
)

bool isChecked = false;

Checkbox(
  value: isChecked,
  onChanged: (value) => setState(() => isChecked = value!),
)

bool darkMode = false;

Switch(
  value: darkMode,
  activeColor: Colors.purple,
  onChanged: (value) => setState(() => darkMode = value),
)

final items = List.generate(50, (i) => 'عنصر رقم $i');

ListView.builder(
  itemCount: items.length,
  itemBuilder: (context, index) {
    return ListTile(title: Text(items[index]));
  },
)

Image.network(
  'https://picsum.photos/300/200',
  width: 300,
  height: 200,
  fit: BoxFit.cover,
  loadingBuilder: (context, child, progress) {
    return progress == null ? child : CircularProgressIndicator();
  },
)

syntax:
ScaffoldMessenger.of(context).showSnackBar(
  SnackBar(content: Text('الرسالة')),
);

example:
ElevatedButton(
  onPressed: () {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('تم الحفظ بنجاح ✓'), duration: Duration(seconds: 2)),
    );
  },
  child: Text('حفظ'),
)

syntax:
showDialog(
  context: context,
  builder: (context) => AlertDialog(
    title: Text('العنوان'),
    content: Text('النص'),
    actions: [Widget, ...],
  ),
);

example:
showDialog(
  context: context,
  builder: (context) => AlertDialog(
    title: Text('حذف المهمة؟'),
    content: Text('لا يمكن التراجع عن هذا الإجراء.'),
    actions: [
      TextButton(onPressed: () => Navigator.pop(context), child: Text('إلغاء')),
      TextButton(onPressed: () => Navigator.pop(context, true), child: Text('حذف')),
    ],
  ),
);
